template <typename UnionPtrType>
QuickStartMessagePtr QuickStartMessage::Clone() const {
  switch (tag_) {
    case Tag::kBootstrapConfigurations:
      return NewBootstrapConfigurations(
          mojo::Clone(*data_.bootstrap_configurations));
    case Tag::kWifiCredentials:
      return NewWifiCredentials(
          mojo::Clone(*data_.wifi_credentials));
    case Tag::kNotifySourceOfUpdateResponse:
      return NewNotifySourceOfUpdateResponse(
          mojo::Clone(*data_.notify_source_of_update_response));
    case Tag::kFidoAssertionResponse:
      return NewFidoAssertionResponse(
          mojo::Clone(*data_.fido_assertion_response));
    case Tag::kUserVerificationRequested:
      return NewUserVerificationRequested(
          mojo::Clone(*data_.user_verification_requested));
    case Tag::kUserVerificationResponse:
      return NewUserVerificationResponse(
          mojo::Clone(*data_.user_verification_response));
    case Tag::kUserVerificationMethod:
      return NewUserVerificationMethod(
          mojo::Clone(*data_.user_verification_method));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, QuickStartMessage>::value>::type*>
bool QuickStartMessage::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kBootstrapConfigurations:
      return mojo::Equals(*(data_.bootstrap_configurations), *(other.data_.bootstrap_configurations));
    case Tag::kWifiCredentials:
      return mojo::Equals(*(data_.wifi_credentials), *(other.data_.wifi_credentials));
    case Tag::kNotifySourceOfUpdateResponse:
      return mojo::Equals(*(data_.notify_source_of_update_response), *(other.data_.notify_source_of_update_response));
    case Tag::kFidoAssertionResponse:
      return mojo::Equals(*(data_.fido_assertion_response), *(other.data_.fido_assertion_response));
    case Tag::kUserVerificationRequested:
      return mojo::Equals(*(data_.user_verification_requested), *(other.data_.user_verification_requested));
    case Tag::kUserVerificationResponse:
      return mojo::Equals(*(data_.user_verification_response), *(other.data_.user_verification_response));
    case Tag::kUserVerificationMethod:
      return mojo::Equals(*(data_.user_verification_method), *(other.data_.user_verification_method));
  }

  return false;
}
